    level: document.querySelector('#levelValue'), levelName: document.querySelector('#levelName'),
    status: document.querySelector('#statusPill'), overlay: document.querySelector('#centerMessage'),
    title: document.querySelector('#messageTitle'), body: document.querySelector('#messageBody'),
    launch: document.querySelector('#launchButton'), launchText: document.querySelector('#launchText'),
    foot: document.querySelector('#messageFoot'), toast: document.querySelector('#toast'),
    progress: document.querySelector('#scoreProgress'), soundIcon: document.querySelector('#soundIcon'),
  };
  const W = 900, H = 570;
  const palette = ['#ff659f','#ffb45e','#c7f16b','#5ce0e8','#a98bff','#ff7bca'];
