  let soundOn = true, audio, toastTimer = 0, shake = 0, launchBall;
  const maxBalls = 54;
  const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
  const rnd = (a,b) => a + Math.random() * (b-a);
