  const format = n => String(Math.max(0, Math.floor(n))).padStart(6,'0');
  ui.best.textContent = format(best);

  function resize() {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.max(1, Math.round(rect.width * dpr)); canvas.height = Math.max(1, Math.round(rect.height * dpr));
    scaleX = canvas.width / W; scaleY = canvas.height / H;
    ctx.setTransform(scaleX, 0, 0, scaleY, 0, 0);
  }
  window.addEventListener('resize', resize); new ResizeObserver(resize).observe(canvas);
  for(let i=0;i<75;i++) stars.push({x:Math.random()*W,y:Math.random()*H,r:rnd(.4,1.3),a:rnd(.12,.6),p:rnd(0,7)});
  function makePaddle(){return {x:W/2-57,y:H-46,w:114,h:12,target:W/2};}
  function makeBricks(stage=level){
    const rows = 4 + Math.min(2, Math.floor((stage-1)/2));
    const cols = 8; const gap=9; const bw=76; const left=(W-(cols*bw+(cols-1)*gap))/2;
    const out=[];
    for(let r=0;r<rows;r++) for(let c=0;c<cols;c++){
      if(stage>1 && (r+c+stage)%11===0) continue;
      const color=palette[(r+stage-1)%palette.length];
      out.push({x:left+c*(bw+gap),y:76+r*39,w:bw,h:22,color,alive:true,hp:stage>3&&r===0?2:1,flash:0});
    }
    return out;
  }
  function newBall(x,y,vx,vy){return {x,y,vx,vy,r:7,trail:[],hue:Math.random()};}
  function attachBall(){ balls=[newBall(paddle.x+paddle.w/2,paddle.y-12,0,0)]; launchBall=balls[0]; }
  function resetRun(){score=0;level=1;lives=3;paddle=makePaddle();bricks=makeBricks();particles=[];attachBall();updateUI();setStatus('READY');ui.overlay.classList.remove('hidden');ui.title.innerHTML='READY TO<br><em>FRACTURE?</em>';ui.body.innerHTML='Move your paddle to aim.<br>Tap or press space to launch.';ui.launchText.textContent='START RUN';ui.foot.textContent='EVERY HIT MAKES TWO';state='ready';}
  function updateUI(){
    ui.score.textContent=format(score);ui.best.textContent=format(best);ui.bricks.textContent=String(bricks.filter(b=>b.alive).length).padStart(2,'0');
    ui.count.textContent=String(balls.length).padStart(2,'0');ui.level.textContent=String(level).padStart(2,'0');ui.levelName.textContent=levelNames[(level-1)%levelNames.length];
    ui.multiplier.textContent=`×${(1+Math.min(9,Math.max(0,balls.length-1)*.12)).toFixed(1)}`;
    ui.progress.style.width=`${Math.min(100,(score%5000)/50)}%`;
    ui.lives.innerHTML=Array.from({length:3},(_,i)=>`<span class="life-glyph ${i>=lives?'lost':''}">◆</span>`).join('');ui.lives.setAttribute('aria-label',`${lives} lives`);
  }
  function launch(){if(state==='ready'){state='playing';setStatus('IN PLAY','playing');ui.overlay.classList.add('hidden');if(launchBall){const angle=(-Math.PI/2)+((pointerX-(paddle.x+paddle.w/2))/paddle.w)*.58;const speed=290;launchBall.vx=Math.sin(angle)*speed;launchBall.vy=-Math.cos(angle)*speed;launchBall=null;}sound(440,.07);}}
  function togglePause(){if(state==='playing'){state='paused';setStatus('PAUSED','paused');showOverlay('PAUSED','Take a breath.<br>Your swarm is holding.','RESUME RUN','PRESS P TO CONTINUE');}else if(state==='paused'){state='playing';setStatus('IN PLAY','playing');ui.overlay.classList.add('hidden');}}
  function showOverlay(title,body,button,foot){ui.title.innerHTML=title;ui.body.innerHTML=body;ui.launchText.textContent=button;ui.foot.textContent=foot;ui.overlay.classList.remove('hidden');}
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1050);}
  function sound(freq=260,duration=.045,type='sine'){if(!soundOn)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}catch(e){}}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++){const a=rnd(0,Math.PI*2),s=rnd(35,190);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rnd(.25,.65),max:.65,color,size:rnd(1.3,3.3)});}}
  function split(ball,angleOffset=0){
    if(balls.length>=maxBalls)return;
    const speed=Math.hypot(ball.vx,ball.vy)||300;
    let angle=Math.atan2(ball.vy,ball.vx);
    const spread=.24+rnd(-.07,.08);
    const a=angle+spread+angleOffset;
    const b=angle-spread+angleOffset;
    ball.vx=Math.cos(a)*speed;ball.vy=Math.sin(a)*speed;
    const clone=newBall(ball.x+Math.cos(b)*2,ball.y+Math.sin(b)*2,Math.cos(b)*speed,Math.sin(b)*speed);
    clone.trail=ball.trail.slice(-3);balls.push(clone);
    if(balls.length===maxBalls)showToast('MAXIMUM FRACTURE');
  }
  function collideRect(ball,rect){
    const nx=clamp(ball.x,rect.x,rect.x+rect.w),ny=clamp(ball.y,rect.y,rect.y+rect.h),dx=ball.x-nx,dy=ball.y-ny;
    if(dx*dx+dy*dy>ball.r*ball.r)return false;
    const overlapX=ball.r-Math.abs(dx),overlapY=ball.r-Math.abs(dy);
    if(overlapX<overlapY){ball.x+=(dx>0?1:-1)*overlapX;ball.vx=Math.abs(ball.vx)*(dx>0?1:-1);}else{ball.y+=(dy>0?1:-1)*overlapY;ball.vy=Math.abs(ball.vy)*(dy>0?1:-1);}
    return true;
  }
  function hit(ball,brick){
    if(!brick.alive)return;
    brick.hp--;brick.flash=.12;
    const color=brick.color;burst(ball.x,ball.y,color,brick.hp?5:9);
    if(brick.hp<=0){brick.alive=false;score+=100+Math.floor(Math.max(0,balls.length-1)*8);if(score>best){best=score;localStorage.setItem('shatterline-best',String(best));}}
    else score+=25;
    split(ball);sound(brick.hp?370:520,.055, 'triangle');shake=.08;
  }
  function step(dt){
    const speed=paddle.target;
    if(keys.ArrowLeft||keys.a||keys.A)paddle.x-=470*dt;
    if(keys.ArrowRight||keys.d||keys.D)paddle.x+=470*dt;
    if(!keys.ArrowLeft&&!keys.ArrowRight&&!keys.a&&!keys.d&&!keys.A&&!keys.D)paddle.x+=(speed-paddle.w/2-paddle.x)*Math.min(1,dt*13);
    paddle.x=clamp(paddle.x,28,W-paddle.w-28);
    if(state==='ready'&&balls.length){balls[0].x=paddle.x+paddle.w/2;balls[0].y=paddle.y-12;}
    if(state==='playing'){
      const substeps=Math.max(1,Math.ceil(dt*70));const sd=dt/substeps;
      for(let sub=0;sub<substeps;sub++){
        for(let i=balls.length-1;i>=0;i--){const b=balls[i];b.trail.push({x:b.x,y:b.y});if(b.trail.length>8)b.trail.shift();
          b.x+=b.vx*sd;b.y+=b.vy*sd;
          let collided=false;
          if(b.x-b.r<22){b.x=22+b.r;b.vx=Math.abs(b.vx);collided=true;}
          if(b.x+b.r>W-22){b.x=W-22-b.r;b.vx=-Math.abs(b.vx);collided=true;}
          if(b.y-b.r<26){b.y=26+b.r;b.vy=Math.abs(b.vy);collided=true;}
          if(collided){split(b);sound(210,.035);}
          if(b.vy>0&&b.y+b.r>=paddle.y&&b.y-b.r<=paddle.y+paddle.h&&b.x>=paddle.x-2&&b.x<=paddle.x+paddle.w+2){
            b.y=paddle.y-b.r;const hitPos=clamp((b.x-(paddle.x+paddle.w/2))/(paddle.w/2),-1,1);const angle=-Math.PI/2+hitPos*.92;const s=clamp(Math.hypot(b.vx,b.vy)+2,290,430);b.vx=Math.cos(angle)*s;b.vy=Math.sin(angle)*s;split(b);sound(310,.07);burst(b.x,b.y+5,'#c8f169',4);
          }
          if(b.y>H+20){balls.splice(i,1);continue;}
          let brickHit=null;
          for(const br of bricks){if(br.alive&&collideRect(b,br)){brickHit=br;break;}}
          if(brickHit)hit(b,brickHit);
          const sp=Math.hypot(b.vx,b.vy);if(sp>440){b.vx*=440/sp;b.vy*=440/sp;}else if(sp<275&&sp>0){b.vx*=275/sp;b.vy*=275/sp;}
        }
      }
      if(!bricks.some(b=>b.alive)){level++;bricks=makeBricks();paddle.w=Math.max(82,114-(level-1)*3);balls.forEach(b=>{b.vx*=1.04;b.vy*=1.04;});showToast(`SECTOR ${String(level).padStart(2,'0')} CLEARED`);sound(660,.18,'triangle');}
      if(!balls.length){lives--;updateUI();if(lives<=0){state='over';setStatus('RUN ENDED');showOverlay('SWARM<br><em>LOST.</em>',`You fractured through <strong>${format(score)}</strong> points.<br>Ready for another run?`,'PLAY AGAIN','THE GRID WILL REMEMBER');}else{state='ready';setStatus('LIFE LOST','paused');attachBall();showOverlay('ONE MORE<br><em>CHANCE.</em>',`${lives} ${lives===1?'life':'lives'} left. The swarm is regrouping.`,'CONTINUE','KEEP THE FRACTURE ALIVE');}}
    }
    for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.12,dt);p.vy*=Math.pow(.12,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1);}
    bricks.forEach(b=>b.flash=Math.max(0,b.flash-dt));
    updateUI();
  }
