  function draw(){
    ctx.clearRect(0,0,W,H);ctx.fillStyle='#0a1021';ctx.fillRect(0,0,W,H);
    const glow=ctx.createRadialGradient(W/2,220,10,W/2,260,490);glow.addColorStop(0,'rgba(39,59,103,.22)');glow.addColorStop(1,'rgba(7,11,24,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
