    // glow lines under brick field
    ctx.strokeStyle='rgba(200,241,105,.12)';ctx.setLineDash([2,8]);ctx.beginPath();ctx.moveTo(27,315);ctx.lineTo(W-27,315);ctx.stroke();ctx.setLineDash([]);
