    if(paddle){ctx.save();ctx.shadowColor='#c8f169';ctx.shadowBlur=18;roundRect(paddle.x,paddle.y,paddle.w,paddle.h,6);ctx.fillStyle='#c8f169';ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='rgba(255,255,255,.62)';roundRect(paddle.x+11,paddle.y+2,paddle.w-22,2,2);ctx.fill();ctx.restore();}
    // balls + trails
    for(const b of balls){for(let i=0;i<b.trail.length;i++){const t=b.trail[i],a=(i+1)/b.trail.length;ctx.beginPath();ctx.arc(t.x,t.y,b.r*a*.75,0,Math.PI*2);ctx.fillStyle=`rgba(200,241,105,${a*.13})`;ctx.fill();}ctx.save();ctx.shadowColor='#e9ffad';ctx.shadowBlur=16;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fillStyle='#f7ffd9';ctx.fill();ctx.restore();}
    for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);}ctx.globalAlpha=1;
    if(state==='ready'){ctx.save();ctx.strokeStyle='rgba(200,241,105,.5)';ctx.setLineDash([3,5]);ctx.beginPath();ctx.moveTo(balls[0]?.x||paddle.x+paddle.w/2,paddle.y-18);ctx.lineTo(balls[0]?.x||paddle.x+paddle.w/2,Math.max(40,paddle.y-130));ctx.stroke();ctx.restore();}
  }
  function loop(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;step(dt);draw();requestAnimationFrame(loop);}

